#!/usr/bin/env python3
"""Build the separate async-search report; leave the pagination report intact."""
import html
import itertools
import json
import statistics
import sys
from pathlib import Path
import benchmark as bench
import pilot
import report as pagination_report

NAMES = {'handwork':'Handwork','opencode':'OpenCode','codex':'Codex'}

def median(values):return statistics.median(values) if values else None
def total(values):return sum(values) if all(v is not None for v in values) else None

def main():
    bench.configure();s=pilot.state();out=bench.OUT
    runs=json.loads((out/'attempts.json').read_text())
    assert len(runs)==15,'Wait for all 15 scored attempts'
    optimized = json.loads((bench.ROOT/'benchmarks/optimization/results-final/report-data.json').read_text())
    for key in ('commit', 'model', 'reasoning', 'context', 'prompt_sha256', 'machine'):
        assert s[key] == optimized['state'][key], key
    runs = [dict(r, evidence='benchmarks/async-search/results/') for r in runs if r['harness'] != 'handwork'] + [dict(r, harness='handwork', evidence='benchmarks/optimization/results-final/') for r in optimized['runs'] if r['variant'] == 'optimized']
    runs.sort(key=lambda r: (list(NAMES).index(r['harness']), r['attempt']))
    s['binary_sha256']['handwork'] = optimized['state']['variants']['optimized']['sha256']
    s['handwork'] = optimized['state']['variants']['optimized']['path']
    s.pop('orders', None)
    summary={}
    for h in NAMES:
        rs=[r for r in runs if r['harness']==h]
        summary[h]={'success':sum(r['success'] for r in rs),'attempts':len(rs),'timeouts':sum(r['timeout'] for r in rs),
            'median_peak_mib':median([r['peak_rss_bytes']['harness']/2**20 for r in rs]),
            'median_solved_s':median([r['duration_s'] for r in rs if r['success']]),
            'input_tokens':total([r['input_tokens'] for r in rs]),'output_tokens':total([r['output_tokens'] for r in rs]),'tool_calls':total([r['tool_calls'] for r in rs])}
    pairs=[]
    data={'task':'async-search','state':s,'summary':summary,'runs':runs,'matched_pairs':pairs,
        'preflight':json.loads((out/'preflight.json').read_text()),'controls':s['controls'],
        'installation':{'handwork':{'version':'Updated Handwork · '+s['binary_sha256']['handwork'][:12]},'opencode':{'version':'Recorded OpenCode build'},'codex':{'version':'Recorded Codex build'}},
        'server_isolation':json.loads((out/'server-isolation.json').read_text())}
    data['comparison'] = {'summary': summary, 'runs': runs,
        'updated_cohort': optimized['state']['created'], 'original_cohort': s['created']}
    pilot.write_json(out/'report-data.json',data)
    t,o,c=(summary[h] for h in NAMES)
    reduction=100*(1-t['median_peak_mib']/o['median_peak_mib'])
    headline=f'Updated Handwork completed {t["success"]} of 5 attempts versus {o["success"]} of 5 for OpenCode, while using {abs(reduction):.1f}% {"less" if reduction>=0 else "more"} harness memory.'
    sub=f'Codex completed {c["success"]} of 5. Memory is the median of per-attempt peak sampled harness RSS; test and other tool processes are recorded separately.'
    css=pagination_report.TEMPLATE.split('<style>',1)[1].split('</style>',1)[0]
    page=TEMPLATE.replace('__CSS__',css).replace('__HEADLINE__',html.escape(headline)).replace('__SUB__',sub).replace('__DATA__',json.dumps(data).replace('</','<\\/'))
    target=bench.ROOT/'search-benchmark-results.html';target.write_text(page)
    print(json.dumps({'page':str(target),'headline':headline,'summary':summary,'matched_pairs':pairs},indent=2))

TEMPLATE='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Handwork · Asynchronous search benchmark</title><style>__CSS__
.panel{min-width:0}.matrix th{white-space:normal;min-width:90px}.matrix td{text-align:center}.matrix th:first-child,.matrix td:first-child{text-align:left;min-width:115px}.status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:currentColor;margin-right:5px}.file-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:20px}.file-box{background:#eef0e9;padding:15px;border-radius:5px}.file-box p{font-size:12px;margin:7px 0 0;color:var(--muted)}@media(max-width:700px){.file-grid{grid-template-columns:1fr}}
</style></head><body><main>
<header><div class="brand">handwork<span style="color:var(--green)">.</span> <span class="tag" style="margin-left:18px">Harness lab / 002</span></div><span class="badge">ASYNC SEARCH</span></header>
<div class="hero"><div class="tag">Shared state. Competing requests. One current query.</div><h1>__HEADLINE__</h1><p class="intro">__SUB__</p><div class="meta"><span>GPT-6 Astra · low reasoning</span><span>5 minutes / attempt</span><span>3 harnesses × 5 attempts</span><span>Controlled promises · no network or sleeps in verifier</span></div><div class="note" id="outcome-note"></div></div>
<div class="cards" id="cards"></div>
<section class="panel"><h2>The task: keep the latest search in control.</h2><p>A response for <code>react</code> must not replace <code>react hooks</code>, clear its loading indicator or surface an outdated error. Clearing input must invalidate in-flight work—even when the user later returns to the same query.</p><div class="file-grid"><div class="file-box"><code>src/api/search.ts</code><p>Encodes queries and adapts HTTP responses through an injectable transport.</p></div><div class="file-box"><code>src/search/controller.ts</code><p>Owns query, results, loading, errors and subscriber notifications.</p></div><div class="file-box"><code>src/ui/search-view.ts</code><p>Forwards input events and renders subscribed state.</p></div></div><p class="small" style="margin-top:14px">Existing basic coverage lives in <code>tests/search.test.ts</code>. The agent may make the smallest appropriate fix; it is not required to edit every file.</p></section>
<section class="panel"><div class="section-top"><div><h2>Correctness first. Then compare resources.</h2><p>Updated Handwork is compared with the earlier OpenCode and Codex runs. All three passed 5/5 attempts on the same fixture, prompt, model and settings. These are separate cohorts, not newly matched rounds. The records below use only updated Handwork attempts alongside the earlier OpenCode and Codex attempts.</p></div><label><span class="small">Metric </span><select id="metric" aria-label="Comparison metric"><option value="memory">Peak harness memory</option><option value="time">Completion time</option><option value="input">Input tokens</option><option value="output">Output tokens</option><option value="tools">Tool calls</option></select></label></div><div id="chart"></div><p class="legend" id="chart-note"></p><div id="pairs" class="small"></div></section>
<section class="panel"><div class="section-top"><div><h2>All 15 attempts</h2><p>Pass = completed within budget, all nine independent groups pass, existing tests pass, protected files unchanged and no task dependencies installed.</p></div><button id="download">Download results JSON</button></div><div class="table-wrap"><table><thead><tr><th>Attempt</th><th>Harness</th><th>Result</th><th>Time</th><th>Harness RSS</th><th>Test RSS</th><th>Input / output</th><th>Tools</th><th>Evidence</th></tr></thead><tbody id="runs"></tbody></table></div><p class="small">RSS is sampled. Test RSS refers to agent-launched tests; other tools and post-run checks have separate records in the JSON. Very short peaks can be missed.</p></section>
<section class="panel"><h2>The independent checks</h2><p class="small">The verifier mounts the real view, drives its input handler, calls the real API adapter with a controlled transport, and checks controller snapshots and rendered state. It also rejects stale subscriber notifications. Each repeated-query and three-request group tests all six completion orders.</p><div class="table-wrap"><table class="matrix"><thead id="matrix-head"></thead><tbody id="matrix"></tbody></table></div><details><summary>Inspect failures, if any</summary><pre id="failures"></pre></details></section>
<section class="grid"><div class="panel"><h2>The verifier was tested first.</h2><p class="small">All three fixture controls pass the existing basic tests. Only the known-correct identity guard passes every independent group. The query-string-only guard must fail A → B → A.</p><div class="table-wrap"><table><thead><tr><th>Control</th><th>Independent groups</th><th>Existing tests</th></tr></thead><tbody id="controls"></tbody></table></div><details><summary>Control details</summary><pre id="control-details"></pre></details></div></section>
<section class="panel methods"><h2>Protocol and limits</h2><div class="method"><div><strong>Verify the fixture before scoring</strong><p>Broken, known-correct and query-string-only variants are tested before the first agent run. Every scored workspace is then cloned from the same broken starting commit. Node 24 executes TypeScript directly; task dependencies are empty and the lockfile is prepared beforehand.</p><p id="commit"></p></div></div><div class="method"><div><strong>Keep verification inaccessible</strong><p>The corrected macOS sandbox preserves ancestor traversal and denies verifier, benchmark source, and sibling workspaces, including reads through symlinks. Every harness passes native read/edit/shell preflight. The local report server is stopped during scoring to prevent HTTP access to protected source files.</p></div></div><div class="method"><div><strong>Five attempts per harness on the same hardware</strong><p id="order"></p><p>Fresh sessions, identical user prompt, GPT-6 Astra with low reasoning, and a 272,000-token client/catalog context. Native system prompts and tool interfaces remain harness-specific. The updated Handwork attempts came from a later alternating comparison. They are not presented as jointly rotated rounds with OpenCode and Codex.</p></div></div><div class="method"><div><strong>Measure the whole task and retain all outcomes</strong><p>Completion time runs from process launch with prompt supplied through process exit, with a 300-second cutoff. Process RSS is sampled using the same instrumentation as pagination; harness, tests and other tools are separate. Token totals sum client-reported usage across model calls, including cached input and reported reasoning output. OpenCode totals include its exploration subagents, recovered from saved session records; the original parent-only counts are retained in the JSON. Tool calls count native invocations, including failed calls—not individual commands within one shell invocation. OpenCode has a fixed session title to avoid auxiliary title generation.</p></div></div><div class="method"><div><strong>Read this as a small hosted-model experiment</strong><p>Five attempts per harness on one fixture do not establish broad superiority or statistically reliable speed differences. Hosted backend hardware, quantization, model-server memory and model cold-start cannot be fixed or observed. Service load and prompt caching affect elapsed times. Codex means the app-bundled CLI; the desktop UI and orchestrator are excluded from harness RSS.</p></div></div><details><summary>Exact prompt</summary><pre id="prompt"></pre></details><details><summary>Preflight, hardware and versions</summary><pre id="metadata"></pre></details></section>
<footer><div>Measured async-search runs · <a href="benchmarks/async-search/results/report-data.json">Raw results</a> · <a href="benchmarks/async-search/benchmark.py">Runner</a> · <a href="benchmarks/async-search/verify.mjs">Verifier</a></div><div><a href="https://developers.openai.com/api/docs/models/gpt-6-astra">Model reference</a></div></footer>
</main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),names={handwork:'Updated Handwork',opencode:'OpenCode',codex:'Codex'},keys=Object.keys(names),colors={handwork:'#20714c',opencode:'#687dd3',codex:'#ae7445'};
const f=(x,n=1)=>x==null?'Unavailable':Number(x).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}),mib=x=>f(x/1048576),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const median=a=>{a=[...a].sort((x,y)=>x-y);return a.length?(a[Math.floor(a.length/2)]+a[Math.floor((a.length-1)/2)])/2:null};
const evidence='benchmarks/async-search/results/';
document.getElementById('outcome-note').textContent=D.runs.every(r=>r.success)?'All 15 attempts passed. Memory and completion timing therefore compare completed fixes of the same bug. Treat this as a pilot, not a general coding ranking.':'Some attempts failed. Their resource use remains included; speed comparisons below exclude unmatched failures.';
document.getElementById('cards').innerHTML=keys.map(h=>{const s=D.summary[h];return `<article class="card" style="--accent:${colors[h]}"><h2>${names[h]}</h2><div class="small">${esc(D.installation[h].version)}</div><div class="success">${s.success} / ${s.attempts} <small>verified fixes</small></div><div class="small">${f(s.success/s.attempts*100,0)}% success · ${s.timeouts} timeouts</div><div class="stats"><div><strong>${f(s.median_peak_mib)} <span>MiB</span></strong><span>Median peak harness RSS</span></div><div><strong>${f(s.median_solved_s)} <span>${s.median_solved_s==null?'':'sec'}</span></strong><span>Median solved time</span></div></div></article>`}).join('');
const C=D.comparison,comparisonNames={...names,handwork:'Updated Handwork'};
function draw(){const type=document.getElementById('metric').value,common=[1,2,3,4,5].filter(a=>keys.every(h=>C.runs.some(r=>r.harness===h&&r.attempt===a&&r.success)));let note='',unit='',values=[];for(const h of keys){const s=C.summary[h];let value;if(type==='memory'){value=s.median_peak_mib;unit=' MiB';note='Median of per-attempt peak sampled harness RSS. Test and tool subprocesses excluded. All five attempts per harness included.'}if(type==='time'){value=median(C.runs.filter(r=>r.harness===h&&common.includes(r.attempt)).map(r=>r.duration_s));unit=' sec';note='Median completion time for five successful attempts per harness. Updated Handwork was run in a later cohort; hosted service load and caching can differ.'}if(type==='input'){value=s.input_tokens;unit=' tokens';note='Input tokens summed across all calls and five attempts, including cache hits.'}if(type==='output'){value=s.output_tokens;unit=' tokens';note='Reported output tokens summed across all calls and five attempts, including reported reasoning output.'}if(type==='tools'){value=s.tool_calls;unit=' calls';note='Native tool invocations across five attempts, including descendant sessions. One invocation can execute several shell commands.'}values.push({h,value})}const max=Math.max(...values.map(x=>x.value||0),1);document.getElementById('chart').innerHTML=values.map(({h,value})=>`<div class="chart-row"><strong>${comparisonNames[h]}</strong><div class="track"><div class="bar" style="width:${value==null?0:Math.max(value/max*100,1)}%;background:${colors[h]}"></div></div><span class="value">${f(value,['input','output','tools'].includes(type)?0:1)}${value==null?'':unit}</span></div>`).join('');document.getElementById('chart-note').textContent=note}
document.getElementById('metric').addEventListener('change',draw);draw();
document.getElementById('pairs').textContent=`Updated Handwork / OpenCode: median ${f(C.summary.handwork.median_solved_s)} / ${f(C.summary.opencode.median_solved_s)} seconds. Updated Handwork / Codex: median ${f(C.summary.handwork.median_solved_s)} / ${f(C.summary.codex.median_solved_s)} seconds. Updated cohort: ${C.updated_cohort}; earlier cohort: ${C.original_cohort}.`;
document.getElementById('runs').innerHTML=D.runs.map(r=>`<tr><td>${r.attempt}</td><td>${names[r.harness]}</td><td class="${r.success?'pass':'fail'}">${r.timeout?'Timeout':r.success?'Pass':'Fail'}</td><td>${f(r.duration_s)}s</td><td>${mib(r.peak_rss_bytes.harness)} MiB</td><td>${mib(r.peak_rss_bytes.tests)} MiB</td><td>${f(r.input_tokens,0)} / ${f(r.output_tokens,0)}</td><td>${f(r.tool_calls,0)}</td><td><a href="${r.evidence}${r.log}.diff">diff</a> · <a href="${r.evidence}${r.log}.stdout">log</a> · <a href="${r.evidence}${r.log}.verify.stdout">checks</a></td></tr>`).join('');
const labels=['Ordinary success','Stale success after latest','Stale success while pending','Stale failure while pending','Latest failure','Clear immediately','Finish after clear','A → B → A','Three request orders'];
document.getElementById('matrix-head').innerHTML='<tr><th>Attempt</th>'+labels.map((x,i)=>`<th title="${esc(D.controls.known_correct.checks[i].name)}">${x}</th>`).join('')+'</tr>';
document.getElementById('matrix').innerHTML=D.runs.map(r=>`<tr><td>${names[r.harness]} ${r.attempt}</td>${labels.map((_,i)=>`<td class="${r.checks[i]?.pass?'pass':'fail'}" title="${esc(r.checks[i]?.error||'')}">${r.checks[i]?.pass?'Pass':r.checks[i]?'Fail':'N/A'}</td>`).join('')}</tr>`).join('');
document.getElementById('failures').textContent=JSON.stringify(D.runs.filter(r=>!r.success).map(r=>({harness:r.harness,attempt:r.attempt,timeout:r.timeout,protected_files_unchanged:r.protected_files_unchanged,checks:r.checks.filter(c=>!c.pass)})),null,2);
const controlNames={broken:'Planted bug',known_correct:'Known-correct identity guard',query_string_only:'Query-string-only guard'};
document.getElementById('controls').innerHTML=Object.entries(D.controls).map(([k,c])=>`<tr><td>${controlNames[k]}</td><td>${c.checks.filter(x=>x.pass).length} / 9</td><td class="${c.existing_tests_pass?'pass':'fail'}">${c.existing_tests_pass?'Pass':'Fail'}</td></tr>`).join('');
document.getElementById('control-details').textContent=JSON.stringify(D.controls,null,2);
document.getElementById('commit').innerHTML='Starting commit: <code>'+esc(D.state.commit)+'</code>.';
document.getElementById('order').textContent='Updated Handwork: '+C.updated_cohort+'. OpenCode and Codex: '+C.original_cohort+'. Results were collected in separate cohorts.';
document.getElementById('prompt').textContent=D.state.prompt;
document.getElementById('metadata').textContent=JSON.stringify({machine:D.state.machine,model:D.state.model,reasoning:D.state.reasoning,context:D.state.context,binary_sha256:D.state.binary_sha256,preflight:D.preflight,installation:D.installation},null,2);
document.getElementById('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='async-search-benchmark.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
</script></body></html>'''

if __name__=='__main__':main()
